    pub(crate) const fn announcement_has(announcement: &Announcement) -> bool {
        match announcement {
            Announcement::NoticeDefaultChosen { .. } => true,
            Announcement::HeadingAnchorGenerated { .. } => false,
            Announcement::FootnoteNameGenerated { .. } => false,
            Announcement::FootnoteNameTaken { .. } => true,
            Announcement::CalloutKindUnknown { .. } => false,
            Announcement::CalloutMetadataIgnored { .. } => false,
            Announcement::EmbedInlineLinked { .. } => true,
            Announcement::EmbedSizeIgnored { .. } => false,
            Announcement::EmbedFileLinked { .. } => false,
            Announcement::EmbedFootnoteDropped { .. } => false,
            Announcement::LinkTargetAttached { .. } => true,
            Announcement::FormatObsidianChosen => false,
            Announcement::FormatPinChosen { .. } => true,
            Announcement::SiteHomeGenerated => true,
            Announcement::FactDateBound { .. } => true,
            Announcement::FeedPostUndated => true,
            Announcement::FeedPostNone => false,
            Announcement::SourceOutputSkipped { .. } => false,
            Announcement::FileIgnoreInferred { .. } => true,
            Announcement::SourceCacheSkipped { .. } => false,
            Announcement::SourceLinkSkipped { .. } => false,
            Announcement::SourceGitChosen { .. } => true,
            Announcement::SourceHistoryAbsent { .. } => true,
            Announcement::SourceHistoryShallow { .. } => true,
            Announcement::SourceHistoryMoved { .. } => true,
            Announcement::SourceSubmoduleSkipped { .. } => false,
            Announcement::SourceLfsPointer { .. } => true,
            Announcement::BuildRecordUnread { .. } => true,
            Announcement::BuildAddressDefault { .. } => true,
            Announcement::PluginComponentUsed { .. } => false,
            Announcement::CodeLanguageUnknown { .. } => true,
            Announcement::ImageAnimationKept { .. } => false,
            Announcement::ImageFormatKept { .. } => true,
            Announcement::RenderCacheCold { .. } => false,
            Announcement::RenderCacheUsed { .. } => false,
            Announcement::RenderCacheUnkeyed { .. } => false,
            Announcement::CacheFolderUnusable { .. } => true,
            Announcement::CacheEntryCorrupt { .. } => false,
            Announcement::CacheEntryUnwritten { .. } => false,
            Announcement::CacheEntryEvicted { .. } => false,
            Announcement::AuthTokenRetired { .. } => true,
        }
    }
    /// Writes nothing for a code without a fix; `Fix` is only made for one that has.
    pub(crate) fn problem(problem: &Problem, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        match problem {
            Problem::ConfigSyntaxInvalid { .. } => {
                write!(out, "fix the TOML at the marked place; nothing else in ink.toml is read until it parses")
            }
            Problem::ConfigKeyUnknown { .. } => {
                write!(out, "remove it; `ink pin <path> <code>` writes a pin where it belongs")
            }
            Problem::ConfigKeyMisplaced { table, .. } => {
                write!(out, "move it under the file it pins, such as `[{table}.\"posts/x.md\"]`")
            }
            Problem::ConfigValueInvalid { .. } => Ok(()),
            Problem::FrontmatterSyntaxInvalid { .. } => {
                write!(out, "fix the YAML between the `---` lines")
            }
            Problem::FrontmatterValueInvalid { .. } => {
                write!(out, "change the value at the marked place, or remove the key")
            }
            Problem::FrontmatterKeyConflict { .. } => {
                write!(out, "keep one of the two keys")
            }
            Problem::SourceFileEncoding { .. } => write!(out, "save the file as UTF-8"),
            Problem::LinkTargetMissing { .. } => Ok(()),
            Problem::LinkAnchorMissing { .. } => {
                write!(out, "write the anchor of a heading of the page, or remove the link")
            }
            Problem::LinkTargetAmbiguous { .. } => {
                write!(out, "write the path of the one you mean")
            }
            Problem::LinkTargetUnpublished { target, .. } => {
                write!(out, "publish {target}, or remove the link")
            }
            Problem::PageRouteCollision { .. } => {
                write!(out, "pin a different `page.slug` on all but one")
            }
            Problem::HtmlElementStripped { .. } => Ok(()),
            Problem::PageNestingDeep { .. } => {
                write!(out, "nest lists, quotes and emphasis less deeply")
            }
            Problem::SourceFileUnreadable { .. } => Ok(()),
            Problem::SourceBudgetFiles { .. } => {
                write!(out, "exclude folders that are not part of the site in ink.toml")
            }
            Problem::SourceBudgetFile { .. } => Ok(()),
            Problem::ThemeRouteCollision { file, .. } => {
                write!(out, "pin a different `page.slug` on {file}")
            }
            Problem::RenderPageFailed { .. } => Ok(()),
            Problem::LinkTargetAsset { target, .. } => {
                write!(out, "link to a page, or show {target} as an image")
            }
            Problem::PinTargetUnpublished { path, .. } => {
                write!(out, "pin a published page, or publish {path}")
            }
            Problem::RouteSegmentUnnamed { .. } => {
                write!(out, "rename it, or pin `page.slug`")
            }
            Problem::AssetMediaUnknown { .. } => Ok(()),
            Problem::ThemeRouteReserved { .. } => {
                write!(out, "choose another theme, or ask its author to move the file")
            }
            Problem::ThemePageRefused { .. } => {
                write!(out, "see the cause below; choose another theme if it persists")
            }
            Problem::SourceBlobMissing { .. } => {
                write!(out, "build again; report it if it persists")
            }
            Problem::EngineDecisionRepeated { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineDecisionMissing { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::PagePublishUnstated { .. } => {
                write!(
                    out,
                    "report it: this is a bug in uses.ink; `ink explain --why` shows the rule that published it"
                )
            }
            Problem::EngineDecisionUnstable { .. } => {
                write!(
                    out,
                    "nothing to do in the site; if the new value is wrong, report it with what `ink explain --why` shows"
                )
            }
            Problem::EngineHeaderInvalid { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineRouteInvalid { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EnginePathInvalid { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineLanguageInvalid { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineRouteRepeated { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineSiteRefused => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineXmlUnwritten { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineKeyUnwritten { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineDateUnrepresentable { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::EngineImageMiscounted { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::SourceBudgetBytes { .. } => {
                write!(out, "move large files that are not part of the site out of the folder")
            }
            Problem::SourceLinkOutside { .. } => {
                write!(out, "copy what it links to into the folder")
            }
            Problem::SourceLinkCycle { .. } => write!(out, "remove the link"),
            Problem::SourceNameInvalid { .. } => {
                write!(out, "rename it: a name is UTF-8 text without `\\`")
            }
            Problem::SourceFileSpecial { .. } => write!(out, "move it out of the folder"),
            Problem::SourceRootUnreadable { .. } => Ok(()),
            Problem::SourceBlobUnwritable { .. } => Ok(()),
            Problem::SourceBudgetFolders { .. } => {
                write!(out, "move folders that are not part of the site out of the folder")
            }
            Problem::SourceRepositoryUnreadable { .. } => {
                write!(
                    out,
                    "check the repository with `git fsck`, or build the files as a folder with `--source folder`"
                )
            }
            Problem::SourceGitNetwork { .. } => {
                write!(out, "the operator of the builder allows it, or the site is built from a folder")
            }
            Problem::SourceGitAuth { .. } => {
                write!(out, "give the builder a credential of that name, or make the repository public")
            }
            Problem::SourceGitTransport { .. } => {
                write!(out, "build the site from a folder or a local repository")
            }
            Problem::SourceGitRevision { .. } => {
                write!(out, "name a branch, tag or commit that the repository holds")
            }
            Problem::SourceBudgetObjects { .. } => {
                write!(out, "fetch a shorter history, or move large generated files out of the repository")
            }
            Problem::SourceRevisionUnknown { .. } => {
                write!(out, "pass a branch, tag or commit id that exists, or leave out `--rev` to read HEAD")
            }
            Problem::SourceLinkBroken { .. } => {
                write!(out, "commit what it links to, or remove the link")
            }
            Problem::MathSyntaxInvalid { .. } => {
                write!(out, "fix the TeX between the `$` signs")
            }
            Problem::ImageBudgetPixels { .. } => {
                write!(out, "export a smaller copy of it and publish that")
            }
            Problem::ImageDecodeFailed { .. } => {
                write!(out, "export it again from an image editor, or remove it from the pages that show it")
            }
            Problem::ImageEncodeFailed { .. } => {
                write!(out, "report it: this is a bug in uses.ink")
            }
            Problem::BlockIdTaken { .. } => {
                write!(out, "give the block an id no heading or other block of the page has")
            }
            Problem::EmbedTargetCycle { .. } => write!(out, "remove one of the embeds"),
            Problem::EmbedAnchorMissing { .. } => {
                write!(out, "write the text of a heading of that page, or a block id it has")
            }
            Problem::EmbedBudgetCount { .. } => {
                write!(out, "embed fewer pages, or link to some of them")
            }
            Problem::VaultSettingsInvalid { .. } => {
                write!(
                    out,
                    "fix the file, or let Obsidian write it again; until then attachments resolve as if no attachment folder were set"
                )
            }
            Problem::AuthSignatureMalformed { .. } => {
                write!(out, "update `ink`; a script that signs its own requests follows the profile in docs/auth.md")
            }
            Problem::AuthTargetNotCanonical { .. } => {
                write!(out, "escape with upper-case hex, sort the query, drop empty pairs; `ink` does this itself")
            }
            Problem::AuthSignatureSkewed { .. } => {
                write!(out, "set this machine's clock, for example `timedatectl set-ntp true`")
            }
            Problem::AuthSignatureRefused => {
                write!(out, "run `ink login` to sign in again on this machine")
            }
            Problem::AuthKeyRevoked { .. } => {
                write!(out, "run `ink login`; for CI, make a new key with `ink key add`")
            }
            Problem::AuthKeyExpired { .. } => {
                write!(out, "run `ink login`; for CI, make a new key with `ink key add`")
            }
            Problem::AuthSignatureReplayed => {
                write!(out, "send a new request; a client that reuses a nonce has a bug")
            }
            Problem::AuthSignatureFlooded { .. } => {
                write!(out, "slow down, and try again in a few seconds")
            }
            Problem::AuthDigestMismatch => {
                write!(out, "send it again; a proxy that changes bodies must not sit between")
            }
            Problem::AuthServerRestarting { .. } => {
                write!(out, "wait; `ink` retries once")
            }
            Problem::AuthRightMissing { .. } => {
                write!(out, "use a key with the right, or approve one with `ink key add`")
            }
            Problem::AuthEnrolmentExpired => write!(out, "run `ink login` again"),
            Problem::AuthEnrolmentDenied => {
                write!(out, "run `ink login` again if it was a mistake")
            }
            Problem::AuthEnrolmentLimited { .. } => {
                write!(out, "wait, then run `ink login` again")
            }
            Problem::AuthEnrolmentLifetime { limit, .. } => {
                write!(out, "ask for {limit} days or fewer with `--expires`")
            }
            Problem::AuthEnrolmentSite => {
                write!(out, "name a site of this account with `--site`")
            }
            Problem::AuthEnrolmentRights => {
                write!(out, "ask for fewer rights with `--right`")
            }
            Problem::AuthEnrolmentMismatch => {
                write!(
                    out,
                    "compare the fingerprint with the terminal that ran `ink login`, and approve only if they match"
                )
            }
            Problem::AuthEnrolmentTaken => {
                write!(out, "use the key you have, or run `ink logout` and `ink login` for a new one")
            }
            Problem::AuthKeyUnknown => write!(out, "list the keys with `ink key list`"),
            Problem::AuthEnrolmentRefused => write!(out, "run `ink login` again"),
            Problem::AuthKeyOperator => {
                write!(out, "delete its line from `<data>/operator-keys`")
            }
            Problem::AuthKeyPrintRefused => {
                write!(out, "send it to a file with `--out`, or redirect stdout")
            }
            Problem::PluginValueUnmirrored { .. } => {
                write!(out, "build the plugin against the same WIT as the host")
            }
            Problem::PluginValueMalformed { .. } => {
                write!(out, "the plugin has a bug; report it to its author")
            }
            Problem::PluginCallTrapped { .. } => {
                write!(out, "the plugin has a bug; report it to its author")
            }
            Problem::PluginBudgetFuel { .. } => Ok(()),
            Problem::PluginBudgetTime { .. } => Ok(()),
            Problem::PluginBudgetMemory { .. } => Ok(()),
            Problem::PluginBudgetTable { .. } => Ok(()),
            Problem::BuildCheckMismatch { .. } => {
                write!(out, "a plugin's component and its native core disagree; `ink build` natively is the reference")
            }
            Problem::AuthOriginRefused => {
                write!(out, "use the dashboard at its own address; a script uses a signed request")
            }
            Problem::AuthPasskeyRefused => {
                write!(out, "try again; if it keeps failing, sign in with an email link and add the passkey again")
            }
            Problem::AuthPasskeyOrigin => {
                write!(out, "open the dashboard at the address the operator configured with `--rp-origin`")
            }
            Problem::AuthPasskeyRelyingParty => {
                write!(out, "use a passkey made for this server, or add one here")
            }
            Problem::AuthPasskeyChallenge => write!(out, "start the ceremony again"),
            Problem::AuthPasskeyUnverified => {
                write!(out, "use an authenticator that verifies you, and approve the prompt")
            }
            Problem::AuthPasskeyCounter => {
                write!(out, "remove the passkey and add a new one; sign in with an email link meanwhile")
            }
            Problem::AuthPasskeyBackup => {
                write!(out, "remove it and add the passkey again")
            }
            Problem::AuthPasskeyMalformed => {
                write!(out, "try again; a browser without passkey support cannot sign in this way")
            }
            Problem::AuthPasskeyAlgorithm => {
                write!(out, "use another authenticator or a platform passkey")
            }
            Problem::AuthPasskeyTaken => {
                write!(out, "sign in with it, or register another authenticator")
            }
            Problem::AuthPasskeyMissing => write!(out, "reload the list"),
            Problem::AuthPasskeyLabel => write!(out, "use a name of 1 to 64 characters"),
            Problem::AuthRelyingPartyChanged { was, .. } => {
                write!(
                    out,
                    "set `--rp-id {was}` again, or accept that people sign in with an email link and add passkeys anew"
                )
            }
            Problem::AuthSessionMissing => write!(out, "reload the list of sessions"),
            Problem::AuthRateLimited => {
                write!(out, "wait the seconds in the Retry-After header, then try again")
            }
            Problem::AuthStepUpRequired => {
                write!(out, "sign in with a passkey again, then repeat the change")
            }
            Problem::AuthRecoveryRefused => {
                write!(out, "check the code, use another, or sign in with a passkey")
            }
            Problem::AuthForwardedRefused => {
                write!(out, "make the proxy send X-Forwarded-For and set the trusted hops to the proxy count")
            }
        }
    }
    /// Writes nothing for a code without a fix; `Fix` is only made for one that has.
    pub(crate) fn announcement(announcement: &Announcement, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        match announcement {
            Announcement::NoticeDefaultChosen { decision, .. } => {
                write!(out, "pin `{decision}` in ink.toml to choose")
            }
            Announcement::HeadingAnchorGenerated { .. } => Ok(()),
            Announcement::FootnoteNameGenerated { .. } => Ok(()),
            Announcement::FootnoteNameTaken { .. } => {
                write!(out, "give the footnotes names that differ in their letters or digits")
            }
            Announcement::CalloutKindUnknown { .. } => Ok(()),
            Announcement::CalloutMetadataIgnored { .. } => Ok(()),
            Announcement::EmbedInlineLinked { .. } => {
                write!(out, "put the embed in a paragraph of its own to show the page")
            }
            Announcement::EmbedSizeIgnored { .. } => Ok(()),
            Announcement::EmbedFileLinked { .. } => Ok(()),
            Announcement::EmbedFootnoteDropped { .. } => Ok(()),
            Announcement::LinkTargetAttached { .. } => {
                write!(out, "write the path of the one you mean")
            }
            Announcement::FormatObsidianChosen => Ok(()),
            Announcement::FormatPinChosen { .. } => {
                write!(out, "remove the pin to read the folder's markdown by what it holds")
            }
            Announcement::SiteHomeGenerated => {
                write!(out, "add index.md or README.md at the root, or pin `site.home`")
            }
            Announcement::FactDateBound { decision, .. } => {
                write!(out, "write the date in the frontmatter, or pin `{decision}`")
            }
            Announcement::FeedPostUndated => {
                write!(out, "write `date:` in its frontmatter, or pin `page.date`")
            }
            Announcement::FeedPostNone => Ok(()),
            Announcement::SourceOutputSkipped { .. } => Ok(()),
            Announcement::FileIgnoreInferred { .. } => {
                write!(out, "add it to `include` in ink.toml to keep it")
            }
            Announcement::SourceCacheSkipped { .. } => Ok(()),
            Announcement::SourceLinkSkipped { .. } => Ok(()),
            Announcement::SourceGitChosen { .. } => {
                write!(out, "pass `--source folder` to read the files as they are, uncommitted changes included")
            }
            Announcement::SourceHistoryAbsent { .. } => {
                write!(out, "write the date in the frontmatter, or build from a git repository")
            }
            Announcement::SourceHistoryShallow { .. } => {
                write!(out, "fetch the whole history, such as with `git fetch --unshallow`")
            }
            Announcement::SourceHistoryMoved { decision, .. } => {
                write!(out, "write the date in the frontmatter of a moved file, or pin `{decision}`")
            }
            Announcement::SourceSubmoduleSkipped { .. } => Ok(()),
            Announcement::SourceLfsPointer { .. } => {
                write!(out, "commit the file itself, or fetch it with `git lfs pull` and build with `--source folder`")
            }
            Announcement::BuildRecordUnread { .. } => {
                write!(out, "nothing to do: this build writes a record the next one reads")
            }
            Announcement::BuildAddressDefault { .. } => {
                write!(out, "pass `--base <url>` with the address the site is served at")
            }
            Announcement::PluginComponentUsed { .. } => Ok(()),
            Announcement::CodeLanguageUnknown { .. } => {
                write!(out, "write a language the highlighter knows after the opening fence, such as `rust` or `toml`")
            }
            Announcement::ImageAnimationKept { .. } => Ok(()),
            Announcement::ImageFormatKept { .. } => {
                write!(out, "publish a JPEG or PNG of it to get smaller copies with the metadata removed")
            }
            Announcement::RenderCacheCold { .. } => Ok(()),
            Announcement::RenderCacheUsed { .. } => Ok(()),
            Announcement::RenderCacheUnkeyed { .. } => Ok(()),
            Announcement::CacheFolderUnusable { .. } => {
                write!(out, "make the folder writable, or pass `--cache <dir>` with one that is")
            }
            Announcement::CacheEntryCorrupt { .. } => Ok(()),
            Announcement::CacheEntryUnwritten { .. } => Ok(()),
            Announcement::CacheEntryEvicted { .. } => Ok(()),
            Announcement::AuthTokenRetired { .. } => {
                write!(out, "sign in with `ink login --data <folder>`, and delete the file")
            }
        }
    }
